#include <bits/stdc++.h>
using namespace std;

class Solution {
    vector<vector<int>> g;
    vector<int> ans;
    string labels;
    array<int, 26> dfs(int u, int parent) {
        array<int, 26> cnt{};
        ++cnt[labels[u] - 'a'];
        for (int v : g[u]) {
            if (v == parent) continue;
            auto child = dfs(v, u);
            for (int j = 0; j < 26; ++j) cnt[j] += child[j];
        }
        ans[u] = cnt[labels[u] - 'a'];
        return cnt;
    }
public:
    vector<int> countSubTrees(int n, vector<vector<int>>& edges, string labels_) {
        g.assign(n, {}); ans.assign(n, 0); labels = labels_;
        for (auto& e : edges) { g[e[0]].push_back(e[1]); g[e[1]].push_back(e[0]); }
        dfs(0, -1);
        return ans;
    }
};
